179	Training (readout $R^2$) & $+$0.045 & [$+$0.032, $+$0.058] & $<$0.0001 \\
180	Proj.\ vs.\ image\_mean ($R^2$) & $+$0.031 & --- & $<$0.001 \\
181	\bottomrule
182	\end{tabular}
183	\end{table}
